draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw dog
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 20);
  ctx.lineTo(W/2 - 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 30);
  ctx.lineTo(W/2 - 70, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 30);
  ctx.lineTo(W/2 - 30, H/2 + 50);
  ctx.stroke();

  // draw blind owner
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 20);
  ctx.lineTo(W/2 + 50, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 30);
  ctx.lineTo(W/2 + 30, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 + 30);
  ctx.lineTo(W/2 + 70, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 40, H/2 - 10);
  ctx.lineTo(W/2 + 60, H/2 - 10);
  ctx.stroke();

  // draw curb
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(0, H - 20 + 10 * Math.sin(t));
  ctx.lineTo(W, H - 20 + 10 * Math.sin(t));
  ctx.stroke();

  // draw dog stopping
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H/2 + 50);
  ctx.lineTo(W/2 - 50, H - 20 + 10 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
